  for (const key of ['inputsSha256', 'protocolSha256', 'provider', 'model', 'reasoningEffort', 'preflight', 'cases', 'sourceHashes']) {
    assert.throws(() => validateReaderContinuationParent(frozen, { ...current, [key]: 'changed' }), /changes frozen/)
